INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: medium / L2 — QTIP trust election and marital deduction
(3, 'Estate and Gift Tax', 'Bancroft dies in 2026, leaving $6,000,000 in a trust that provides all income to his wife, Elaine, for life, with the remainder passing to their children. The executor elects qualified terminable interest property (QTIP) treatment on the estate tax return. What is the estate tax effect of the QTIP election?', '["The trust is excluded from the gross estate entirely", "The trust qualifies for a partial marital deduction equal to Elaine''s life interest", "The trust qualifies for a full marital deduction, deferring estate tax until Elaine''s death", "The trust is taxed at a reduced rate of 20% instead of 40%"]'::jsonb, 2, 'Under IRC Section 2056(b)(7), a QTIP election allows the executor to claim a full marital deduction for trust property that provides all income to the surviving spouse for life, even though the spouse does not control the remainder. This defers estate tax until the surviving spouse''s death, when the trust is included in her estate under Section 2044. Choice B is incorrect because the deduction covers the entire trust value, not just the income interest.', 'medium', 2),

-- Q2: medium / L3 — Section 2035 three-year inclusion rule for life insurance
(3, 'Estate and Gift Tax', 'Palmer transferred a $1,500,000 life insurance policy to an irrevocable trust on March 10, 2024. Palmer retained no incidents of ownership after the transfer. Palmer dies on January 5, 2026. How does the timing of this transfer affect the estate tax treatment of the policy proceeds?', '["The proceeds are excluded from Palmer''s gross estate because the transfer was completed before death", "The proceeds are included in Palmer''s gross estate because the transfer occurred within three years of death", "The proceeds are partially included based on the proportion of premiums paid before the transfer", "The proceeds are excluded because Palmer held no incidents of ownership at death"]'::jsonb, 1, 'Under IRC Section 2035(a), any transfer of a life insurance policy within three years of the decedent''s death causes the proceeds to be pulled back into the gross estate. Because Palmer transferred the policy in March 2024 and died in January 2026 — less than three years later — the full death benefit is includable. Choice D is incorrect because Section 2035 overrides the lack of incidents of ownership when the transfer falls within the three-year window.', 'medium', 3),

-- Q3: easy / L1 — Present interest requirement for annual exclusion
(3, 'Estate and Gift Tax', 'Under IRC Section 2503(b), what type of interest must a gift convey to qualify for the annual exclusion?', '["A present interest", "A future interest", "A vested remainder interest", "An income interest in trust"]'::jsonb, 0, 'Under IRC Section 2503(b), the annual gift tax exclusion applies only to gifts of present interests — the right to immediate use, possession, or enjoyment of the property. Future interests, including reversions and remainders, do not qualify. Choice B is incorrect because future interests are specifically excluded from the annual exclusion, which is why Crummey withdrawal powers are used to convert future interests into present interests.', 'easy', 1),

-- Q4: easy / L1 — General power of appointment inclusion
(3, 'Estate and Gift Tax', 'Under IRC Section 2041, what is the estate tax consequence of holding a general power of appointment at death?', '["The power is disregarded for estate tax purposes", "The property is included only if the power was actually exercised", "The property is included only if the power was created by the decedent", "The property subject to the power is included in the decedent''s gross estate"]'::jsonb, 3, 'Under IRC Section 2041(a)(2), property subject to a general power of appointment held by the decedent at death is included in the gross estate, regardless of whether the power was exercised. A general power allows the holder to appoint property to themselves, their estate, or their creditors. Choice B is incorrect because mere possession of the power at death triggers inclusion, even if the decedent never exercised it.', 'easy', 1),

-- Q5: medium / L2 — Below-market loan gift tax under Section 7872
(3, 'Estate and Gift Tax', 'On January 1, 2026, Weston lends $800,000 to his daughter, Keeley, at 0% interest for an indefinite term. The applicable federal rate is 4.5%. Under Section 7872, what is the approximate annual gift tax consequence of this arrangement?', '["No gift because loans are not subject to gift tax", "$36,000 treated as an annual gift from Weston to Keeley", "$800,000 treated as an immediate gift of the full loan principal", "$19,000 per year limited to the annual exclusion amount"]'::jsonb, 1, 'Under IRC Section 7872, below-market loans between family members are treated as if the lender made a gift equal to the forgone interest. For a demand loan of $800,000 at 0% when the AFR is 4.5%, the imputed interest is approximately $36,000 per year ($800,000 x 4.5%), which is treated as a taxable gift. Choice A is incorrect because Section 7872 specifically recharacterizes below-market loans as having a gift component equal to the forgone interest.', 'medium', 2),

-- Q6: easy / L1 — Qualified domestic trust for non-citizen spouse
(3, 'Estate and Gift Tax', 'Under IRC Section 2056A, what is the purpose of a qualified domestic trust (QDOT)?', '["To defer capital gains tax on inherited property", "To avoid generation-skipping transfer tax on trust distributions", "To allow an estate tax marital deduction for property passing to a non-citizen surviving spouse", "To shelter trust income from state income tax"]'::jsonb, 2, 'Under IRC Section 2056A, a qualified domestic trust (QDOT) permits the estate to claim the unlimited marital deduction when the surviving spouse is not a U.S. citizen. Without a QDOT, the marital deduction is denied for transfers to non-citizen spouses because of the risk that the surviving spouse may leave the U.S., placing the assets beyond IRS reach. Choice A is incorrect because the QDOT addresses estate tax deferral, not capital gains tax.', 'easy', 1),

-- Q7: easy / L1 — Section 6166 installment payment election
(3, 'Estate and Gift Tax', 'What does IRC Section 6166 allow when a closely held business comprises a significant portion of a decedent''s estate?', '["Deferral and installment payment of estate tax attributable to the business interest", "Complete exemption of the business interest from estate tax", "A special reduced estate tax rate on business assets", "Exclusion of the business interest from the gross estate"]'::jsonb, 0, 'Under IRC Section 6166, if a closely held business interest exceeds 35% of the adjusted gross estate, the executor may elect to pay the estate tax attributable to that interest in installments over up to 14 years, with an initial deferral period of up to 5 years. This provides liquidity relief for estates with illiquid business assets. Choice B is incorrect because Section 6166 does not exempt the business from tax — it only defers the payment schedule.', 'easy', 1),

-- Q8: hard / L4 — Evaluate GRAT vs outright gift strategy
(3, 'Estate and Gift Tax', 'Whitaker, age 60, owns $4,000,000 in closely held stock expected to appreciate 12% annually. Her CPA evaluates two strategies: (1) an outright gift using lifetime exemption, or (2) a two-year grantor retained annuity trust (GRAT) with annuity payments set to zero out the gift value under Section 7520. Whitaker''s primary goal is transferring maximum value to her children with minimal gift tax. Which factor most strongly favors the GRAT over the outright gift?', '["The GRAT produces a larger income tax deduction for the grantor", "The GRAT allows Whitaker to retain voting control of the stock indefinitely", "The GRAT is superior because it avoids all transfer taxes permanently", "The GRAT transfers appreciation above the Section 7520 rate gift-tax-free, preserving the lifetime exemption"]'::jsonb, 3, 'Under IRC Section 2702, a zeroed-out GRAT returns the principal to the grantor via annuity payments while transferring any appreciation exceeding the Section 7520 assumed rate to the remainder beneficiaries gift-tax-free. If the stock appreciates at 12% and the Section 7520 rate is lower, the excess growth passes without using lifetime exemption. Choice C is incorrect because if the grantor dies during the GRAT term, the trust assets are included in the gross estate under Section 2036, so the GRAT does not permanently avoid all transfer taxes.', 'hard', 4),

-- Q9: easy / L1 — Incomplete gift definition
(3, 'Estate and Gift Tax', 'For federal gift tax purposes, when is a transfer considered an incomplete gift?', '["When the donor transfers property to a trust with a Crummey power", "When the donor retains the power to revoke the transfer or change beneficiaries", "When the donor makes a transfer exceeding the annual exclusion amount", "When the donee is a minor child under age 18"]'::jsonb, 1, 'Under IRC Section 2511 and Treas. Reg. Section 25.2511-2, a gift is incomplete if the donor retains dominion and control over the transferred property, such as the power to revoke the trust or redirect the assets to different beneficiaries. An incomplete gift is not subject to gift tax at the time of transfer. Choice A is incorrect because a Crummey power is held by the beneficiary, not the donor, and it actually makes the transfer a completed gift of a present interest.', 'easy', 1),

-- Q10: medium / L2 — Joint tenancy inclusion for non-spouses
(3, 'Estate and Gift Tax', 'Caldwell and her sister, Monroe, hold a beach property as joint tenants with right of survivorship. Caldwell contributed $600,000 of the $750,000 purchase price, and Monroe contributed $150,000. Upon Caldwell''s death, what amount is included in Caldwell''s gross estate?', '["$600,000, the amount Caldwell actually contributed to the purchase", "$375,000, representing one-half of the property''s value", "$750,000, the full value of the property", "$150,000, representing Monroe''s contribution"]'::jsonb, 0, 'Under IRC Section 2040(a), for joint tenancies between non-spouses, the full value of the property is included in the decedent''s gross estate except to the extent the surviving joint tenant can prove their own contribution. Since Monroe can demonstrate she contributed $150,000 of the $750,000 purchase price, only $600,000 is included. Choice B is incorrect because the 50% rule under Section 2040(b) applies only to joint tenancies between spouses.', 'medium', 2),

-- Q11: hard / L4 — Evaluate special use valuation under Section 2032A
(3, 'Estate and Gift Tax', 'The executor of Garrison''s estate is considering the Section 2032A special use valuation election. Garrison''s farm has a fair market value of $5,200,000 and a special use value of $3,400,000. The estate qualifies under all statutory tests. However, Garrison''s heirs plan to sell the farm within two years to a developer. Should the executor elect special use valuation, and what risk does the potential sale create?', '["The executor should not elect because special use valuation is limited to a $500,000 reduction", "The executor should elect because the election becomes irrevocable once the return is filed, locking in savings permanently", "The executor should elect with caution because a disposition within 10 years of death triggers recapture of the estate tax savings under Section 2032A(c)", "The executor should not elect because Section 2032A applies only to property passing to a surviving spouse"]'::jsonb, 2, 'Under IRC Section 2032A, special use valuation can reduce the estate''s value by up to $1,310,000 (2026 indexed). However, Section 2032A(c) imposes a recapture tax if the qualified heir disposes of the property or ceases qualified use within 10 years of the decedent''s death. Selling the farm to a developer within two years would trigger full recapture of the tax benefit. Choice B is incorrect because although the election is binding, the tax savings are subject to clawback upon early disposition.', 'hard', 4),

-- Q12: medium / L3 — QTIP inclusion in surviving spouse's estate
(3, 'Estate and Gift Tax', 'Fleming''s husband died in 2020, leaving $4,000,000 in a QTIP trust. Fleming received all income from the trust for life. Fleming dies in 2026, when the trust is worth $5,800,000. Analyze how the QTIP trust affects Fleming''s gross estate and why the inclusion amount may differ from what her husband originally placed in the trust.', '["Nothing is included because Fleming never owned the trust assets", "Only $4,000,000 is included, matching the original contribution to the trust", "Only the income earned during Fleming''s lifetime is included", "The full $5,800,000 date-of-death value is included in Fleming''s gross estate under Section 2044"]'::jsonb, 3, 'Under IRC Section 2044, the entire value of QTIP trust property is included in the surviving spouse''s gross estate at its fair market value on the date of death, not the original funded amount. Because the QTIP election allowed a marital deduction in the first spouse''s estate, Congress requires inclusion in the surviving spouse''s estate to ensure the property is eventually taxed. Choice B is incorrect because Section 2044 values the trust at death, capturing all post-transfer appreciation.', 'medium', 3),

-- Q13: medium / L2 — Adjusted taxable gifts in estate tax computation
(3, 'Estate and Gift Tax', 'Prescott made $3,500,000 in taxable gifts during her lifetime on which she paid $200,000 in gift tax. She dies in 2026 with a gross estate of $12,000,000 and deductions of $1,000,000. To compute the tentative estate tax, the executor adds adjusted taxable gifts to the taxable estate. What is Prescott''s estate tax base?', '["$11,000,000", "$14,500,000", "$11,200,000", "$15,500,000"]'::jsonb, 1, 'Under IRC Section 2001(b), the estate tax base equals the taxable estate ($12,000,000 minus $1,000,000 = $11,000,000) plus adjusted taxable gifts ($3,500,000), totaling $14,500,000. The tentative tax is computed on this combined base, then reduced by gift taxes previously paid and the unified credit. Choice A is incorrect because it reflects only the taxable estate without adding back lifetime taxable gifts, which the unified system requires to determine the correct marginal bracket.', 'medium', 2),

-- Q14: hard / L4 — Evaluate charitable remainder annuity trust planning
(3, 'Estate and Gift Tax', 'Ortega, age 72, holds $3,000,000 in highly appreciated stock (basis $400,000). Her CPA proposes funding a charitable remainder annuity trust (CRAT) paying Ortega 7% annually for life, with the remainder to a qualified charity. Ortega''s primary concern is minimizing estate tax while maintaining income. Evaluate the estate tax advantage of the CRAT compared to holding the stock outright until death.', '["The CRAT removes the stock from Ortega''s gross estate because the charitable remainder qualifies for an estate tax deduction under Section 2055", "The CRAT has no estate tax advantage because the income interest is included in the gross estate at full value", "The CRAT is disadvantageous because the trust must pay capital gains tax on the appreciated stock", "The CRAT only benefits Ortega if she survives more than 10 years after funding the trust"]'::jsonb, 0, 'Under IRC Section 2055, the charitable remainder interest in a CRAT qualifies for an estate tax charitable deduction. If Ortega dies during the trust term, the present value of the charity''s remainder is deductible, and only the present value of any successor annuity interest is taxable. This significantly reduces estate tax exposure compared to holding appreciated stock outright. Choice B is incorrect because Section 2055 specifically provides a deduction for the charitable remainder, offsetting the inclusion of the income interest.', 'hard', 4),

-- Q15: medium / L2 — Life insurance incidents of ownership
(3, 'Estate and Gift Tax', 'Dawson owns a $2,000,000 life insurance policy on his own life payable to his wife, Collins. Dawson can change the beneficiary, borrow against the policy, and cancel it. Dawson dies in 2026. What amount of the policy proceeds is included in Dawson''s gross estate?', '["$0, because the proceeds are payable to a named beneficiary rather than the estate", "Nothing, because life insurance is exempt from estate tax", "$2,000,000, because Dawson held incidents of ownership in the policy at death", "$1,000,000, representing one-half under the marital property rules"]'::jsonb, 2, 'Under IRC Section 2042(2), life insurance proceeds are included in the insured''s gross estate when the decedent possessed any incidents of ownership at death, such as the power to change beneficiaries, borrow against the policy, or surrender it. Dawson held all of these powers. Choice A is incorrect because Section 2042 looks at ownership incidents, not the named beneficiary — proceeds payable to a third party are still includable if the insured retained control over the policy.', 'medium', 2),

-- Q16: medium / L3 — 529 plan five-year election analysis
(3, 'Estate and Gift Tax', 'On April 15, 2026, Rivera contributes $95,000 to a 529 education savings plan for her grandson. Rivera elects under Section 529(c)(2)(B) to spread the gift over five years. The annual exclusion is $19,000. Analyze whether Rivera has made a taxable gift in 2026 and the consequence if she dies in 2028.', '["Rivera has no taxable gift because the five-year election covers the entire $95,000, but if she dies in 2028 the remaining three years'' allocations ($57,000) are included in her gross estate", "Rivera has a $76,000 taxable gift because only the first year qualifies for the annual exclusion", "Rivera has no taxable gift, and death in 2028 has no estate tax consequence because 529 contributions are fully exempt", "Rivera has a $95,000 taxable gift because the five-year election applies only to married couples electing gift splitting"]'::jsonb, 0, 'Under IRC Section 529(c)(2)(B), a contributor may elect to treat a lump-sum contribution as made ratably over five years for gift tax purposes. Rivera''s $95,000 spread over five years equals $19,000 per year, exactly matching the annual exclusion, so no taxable gift results. However, if Rivera dies before the five-year period ends, the portion allocated to years after death is recaptured into her gross estate. Choice B is incorrect because the five-year election specifically permits pro-rata annual exclusion treatment for each allocated year.', 'medium', 3),

-- Q17: medium / L3 — Taxable termination under GST
(3, 'Estate and Gift Tax', 'Fletcher created a trust in 2015 providing income to his daughter, Hartley, for life, with the remainder passing to Hartley''s children. Fletcher allocated his GST exemption to other transfers and has no remaining exemption. Hartley dies in 2026. Analyze the generation-skipping transfer tax consequences when Hartley''s interest terminates.', '["No GST applies because Hartley''s children are natural objects of her bounty", "A taxable distribution occurs, taxed to each grandchild individually at their marginal rate", "The trust terminates without GST because it was created more than 10 years before the triggering event", "A taxable termination occurs under Section 2612(a), and the trust is liable for GST at the maximum estate tax rate on the full trust value"]'::jsonb, 3, 'Under IRC Section 2612(a), a taxable termination occurs when an interest in a trust terminates and thereafter only skip persons hold interests. When Hartley dies and the remainder passes to grandchildren (skip persons), the trust incurs GST. Because Fletcher had no remaining GST exemption to allocate, the full trust value is taxed at the maximum estate tax rate of 40%. Choice A is incorrect because the GST tax is determined by the transferor''s relationship to the beneficiaries, and grandchildren are skip persons regardless of their relationship to the intervening beneficiary.', 'medium', 3),

-- Q18: medium / L3 — Community property estate inclusion and basis
(3, 'Estate and Gift Tax', 'Torres and his wife reside in a community property state. Torres dies in 2026 owning community property with a total value of $6,000,000 and separate property worth $2,000,000. Analyze what is included in Torres''s gross estate and the basis consequences for his surviving wife.', '["Only Torres''s separate property is included because community property passes by operation of law", "One-half of the community property ($3,000,000) plus all separate property ($2,000,000) is included, and the surviving spouse''s community property half also receives a stepped-up basis", "The entire $8,000,000 is included because all marital property belongs to the decedent for estate tax purposes", "Only $5,000,000 is included after applying the automatic marital deduction to one-half of the community property"]'::jsonb, 1, 'Under IRC Section 2033, the decedent''s one-half of community property ($3,000,000) plus all separate property ($2,000,000) is included in the gross estate, totaling $5,000,000. Under IRC Section 1014(b)(6), both halves of community property receive a stepped-up basis at the first spouse''s death — a significant advantage over common-law states. Choice C is incorrect because only the decedent''s half of community property is includable; the surviving spouse already owns the other half outright.', 'medium', 3),

-- Q19: medium / L3 — Valuation discount challenge for family limited partnership
(3, 'Estate and Gift Tax', 'Buchanan transfers $2,000,000 in marketable securities to a family limited partnership (FLP) and then gifts a 40% limited partnership interest to her children. An independent appraiser values the 40% interest at $640,000 after applying a 20% combined discount for lack of control and marketability. Analyze whether the IRS is likely to challenge the valuation.', '["The IRS will not challenge because independent appraisals are conclusive for gift tax purposes", "The IRS has no authority to contest valuation discounts on legitimate partnership interests", "The IRS may challenge under Section 2703 or Section 2704 if the partnership lacks a legitimate business purpose beyond tax reduction, arguing the discounts are artificially inflated", "The IRS will automatically disallow the discount because family members cannot form limited partnerships"]'::jsonb, 2, 'Under IRC Sections 2703 and 2704, the IRS may disregard valuation discounts on family entity transfers if restrictions are deemed applicable retained interests or if the entity lacks a substantial non-tax business purpose. Courts have consistently scrutinized FLPs formed solely to obtain transfer tax discounts with no bona fide business operations. Choice A is incorrect because appraisals are not conclusive — the IRS and courts regularly adjust valuations under the willing-buyer/willing-seller standard of Treasury Regulation Section 25.2512-1.', 'medium', 3),

-- Q20: hard / L4 — Evaluate net gift arrangement
(3, 'Estate and Gift Tax', 'Donovan, age 75, plans to give $8,000,000 in real estate to his three adult children. His CPA presents two options: (1) a standard gift where Donovan pays gift tax from other assets, or (2) a net gift arrangement where the donees agree to pay the resulting gift tax as a condition of the transfer. Donovan has fully used his lifetime exemption. Evaluate which arrangement results in a lower total transfer tax cost and identify the primary risk of the net gift.', '["The net gift produces lower total gift tax because the tax base is reduced by the donees'' obligation to pay the tax, but the donees'' payment may trigger income recognition to Donovan under Diedrich v. Commissioner", "The standard gift is always preferable because net gifts are prohibited under current law", "The net gift eliminates all gift tax liability because the donees'' assumption of the tax obligation is not a taxable event", "Both options produce identical tax results because the gift tax rate applies to the same fair market value regardless of who pays"]'::jsonb, 0, 'In a net gift arrangement, the taxable gift equals the property value minus the gift tax the donees assume, producing a circular computation that yields a lower total tax than a standard gift. However, under Diedrich v. Commissioner (1982), the Supreme Court held that when donees pay gift tax exceeding the donor''s adjusted basis, the donor recognizes income on the excess. Choice D is incorrect because the net gift calculation reduces the tax base, resulting in a mathematically lower total tax than a standard gift on the same property value.', 'hard', 4),

-- Q21: hard / L3 — Section 2036 retained income interest analysis
(3, 'Estate and Gift Tax', 'Marlowe transferred her investment portfolio worth $3,200,000 to an irrevocable trust in 2020 but retained the right to receive all trust income for 10 years. The trust remainder passes to her children. Marlowe dies in 2026, six years into the trust term, when the portfolio is worth $4,500,000. Analyze the estate tax treatment of the trust assets.', '["Only the present value of the remaining four years of income is included in Marlowe''s gross estate", "Only the original $3,200,000 transfer value is included since the transfer was completed in 2020", "Nothing is included because the trust is irrevocable and Marlowe did not retain ownership", "The full $4,500,000 date-of-death value is included in Marlowe''s gross estate because she retained the right to income under Section 2036"]'::jsonb, 3, 'Under IRC Section 2036(a)(1), if a decedent transfers property but retains the right to income or possession for life or for a period that does not end before death, the full date-of-death value is included in the gross estate. Marlowe''s retained income right for 10 years had not expired at her death in year six, triggering full inclusion at $4,500,000. Choice C is incorrect because irrevocability is irrelevant — Section 2036 focuses on whether the decedent retained beneficial enjoyment, not legal ownership.', 'hard', 3),

-- Q22: medium / L2 — Estate deductions for debts under Section 2053
(3, 'Estate and Gift Tax', 'Sutton dies in 2026 with a gross estate of $9,500,000. The estate owes $180,000 in outstanding medical bills, a $1,200,000 mortgage on the primary residence, and $45,000 in credit card debt. The executor also pays $85,000 in attorney fees for estate administration. What is the total amount deductible under Section 2053?', '["$1,425,000", "$1,510,000", "$180,000", "$1,200,000"]'::jsonb, 1, 'Under IRC Section 2053(a), allowable deductions from the gross estate include administration expenses (attorney fees of $85,000) and claims against the estate (debts and mortgages). The total deductible amount is $180,000 + $1,200,000 + $45,000 + $85,000 = $1,510,000. Choice A is incorrect because it omits the $85,000 in attorney fees, which qualify as administration expenses deductible under Section 2053(a)(2).', 'medium', 2),

-- Q23: medium / L2 — Gift tax return filing requirements
(3, 'Estate and Gift Tax', 'In 2026, Nakamura makes the following gifts: $19,000 cash to her nephew, a $30,000 painting to her daughter, and $22,000 tuition paid directly to a university for her grandson. The annual exclusion is $19,000. For which gifts must Nakamura file Form 709?', '["All three gifts because each exceeds $15,000", "Only the $19,000 cash gift because it equals the exclusion threshold", "Only the $30,000 painting to her daughter", "Both the $19,000 cash gift and the $30,000 painting"]'::jsonb, 2, 'Under IRC Section 6019, a donor must file Form 709 for any gift exceeding the annual exclusion amount. The $19,000 cash gift exactly equals the exclusion and does not require filing. The $22,000 tuition payment is excluded under Section 2503(e) as a direct educational payment. Only the $30,000 painting exceeds the $19,000 exclusion, requiring Form 709 to report the $11,000 taxable portion. Choice D is incorrect because a gift exactly equal to the annual exclusion does not trigger a filing requirement.', 'medium', 2),

-- Q24: hard / L4 — Evaluate QPRT benefits and mortality risk
(3, 'Estate and Gift Tax', 'Chambers, age 65, owns a vacation home valued at $2,800,000 and is considering transferring it to a qualified personal residence trust (QPRT) with a 15-year retained term. The gift value for transfer tax purposes would be approximately $900,000 based on IRS actuarial tables. Her CPA warns about the mortality risk. Evaluate whether the QPRT achieves Chambers''s goal of reducing estate tax exposure and identify the primary risk.', '["The QPRT transfers a $2,800,000 asset at a discounted gift value of $900,000, but if Chambers dies during the 15-year term the entire property reverts to her gross estate under Section 2036, eliminating the benefit", "The QPRT is ineffective because the IRS does not permit QPRTs for vacation homes", "The QPRT locks in estate tax savings once funded because the irrevocable gift cannot be reversed by the grantor", "The QPRT is inferior to an outright gift because it always results in higher total transfer tax"]'::jsonb, 0, 'Under IRC Section 2702(a)(3)(A)(ii) and Treasury Regulation Section 25.2702-5, a QPRT freezes the transfer tax value at the discounted remainder interest ($900,000), potentially removing substantial appreciation from the estate. However, if the grantor dies during the retained term, Section 2036 includes the full date-of-death value in the gross estate, nullifying the benefit. Choice C is incorrect because the estate tax savings are contingent on surviving the trust term — the gift is irrevocable but the estate tax benefit is not guaranteed.', 'hard', 4),

-- Q25: easy / L1 — Taxable termination definition under GST
(3, 'Estate and Gift Tax', 'Under IRC Section 2612(a), what event constitutes a taxable termination for generation-skipping transfer tax purposes?', '["A direct transfer from a grandparent to a grandchild", "A distribution from a trust to a skip person while a non-skip person retains an interest", "The death of the grantor of a generation-skipping trust", "The termination of an interest in a trust after which only skip persons hold interests"]'::jsonb, 3, 'Under IRC Section 2612(a), a taxable termination occurs when an interest in a trust terminates — by death, lapse of time, or release — and afterward only skip persons (individuals two or more generations below the transferor) hold interests in the trust. This typically occurs when a child-beneficiary dies and grandchildren become the sole beneficiaries. Choice B describes a taxable distribution under Section 2612(b), not a taxable termination, because a non-skip person still holds an interest.', 'easy', 1),

-- Q26: easy / L1 — State death tax deduction under Section 2058
(3, 'Estate and Gift Tax', 'Under IRC Section 2058, what deduction is available for state-level transfer taxes paid by an estate?', '["No deduction is available because federal and state taxes are entirely separate systems", "A deduction from the gross estate for state death taxes actually paid", "A dollar-for-dollar credit against the federal estate tax liability", "A deduction limited to 10% of the federal estate tax owed"]'::jsonb, 1, 'Under IRC Section 2058, estates may deduct state death taxes paid from the gross estate when computing the federal taxable estate. This replaced the former state death tax credit, which was phased out by the Economic Growth and Tax Relief Reconciliation Act of 2001. Choice C is incorrect because the state death tax credit was eliminated; the current provision under Section 2058 provides only a deduction, which is less valuable than the former credit.', 'easy', 1),

-- Q27: easy / L2 — Future interest gift and annual exclusion denial
(3, 'Estate and Gift Tax', 'On June 1, 2026, Keller transfers $50,000 to an irrevocable trust providing that his daughter, Page, will receive the trust assets when she reaches age 30. Page is currently 22. No withdrawal rights are included. How does the gift tax annual exclusion apply to this transfer?', '["The annual exclusion does not apply because the gift is a future interest", "The full $50,000 qualifies for the annual exclusion because it is an irrevocable transfer", "Only $19,000 qualifies for the annual exclusion, and $31,000 is a taxable gift", "The exclusion applies in full because Page is a lineal descendant"]'::jsonb, 0, 'Under IRC Section 2503(b), the annual gift tax exclusion applies only to gifts of present interests — the immediate right to use, possess, or enjoy the property. Because Page cannot access the trust assets until she turns 30, the gift is a future interest and the entire $50,000 is a taxable gift with no annual exclusion. Choice C is incorrect because there is no partial present-interest treatment — without a Crummey withdrawal power, the entire transfer is a future interest.', 'easy', 2),

-- Q28: medium / L2 — Annuity inclusion under Section 2039
(3, 'Estate and Gift Tax', 'Banks purchased a joint-and-survivor annuity with her own funds in 2018, paying $300,000 for lifetime payments of $2,500 per month to herself, with payments continuing to her son, Carter, after her death. Banks dies in 2026, when the present value of Carter''s survivor annuity is $185,000. What amount is included in Banks''s gross estate?', '["$300,000, the original purchase price of the annuity", "$2,500, representing one month''s payment", "$185,000, the present value of the survivor annuity payable to Carter", "$0, because the annuity terminated at Banks''s death"]'::jsonb, 2, 'Under IRC Section 2039(a), the value of an annuity or payment receivable by a surviving beneficiary is included in the decedent''s gross estate to the extent attributable to the decedent''s contributions. Because Banks funded the entire annuity, the full present value of Carter''s survivor interest ($185,000) is included. Choice A is incorrect because Section 2039 includes the value of the survivor''s benefit at the decedent''s death, not the original purchase price, since Banks''s own life interest terminated.', 'medium', 2),

-- Q29: easy / L1 — Applicable credit amount function
(3, 'Estate and Gift Tax', 'What is the function of the applicable credit amount (unified credit) under IRC Section 2010?', '["It reduces the income tax on inherited assets", "It increases the gross estate threshold for state tax purposes", "It provides a deduction for administrative expenses", "It offsets estate and gift tax on a specified amount of transfers, known as the applicable exclusion amount"]'::jsonb, 3, 'Under IRC Section 2010, the applicable credit amount (unified credit) directly reduces the tentative estate and gift tax, effectively shielding transfers up to the applicable exclusion amount from tax. For 2026, the exclusion amount is approximately $14.50 million per individual. Choice A is incorrect because the unified credit applies exclusively to transfer taxes (estate and gift), not to income taxes on inherited property.', 'easy', 1),

-- Q30: medium / L3 — Qualified disclaimer redirecting estate assets
(3, 'Estate and Gift Tax', 'Barrett inherits $1,200,000 from her mother''s estate. Barrett is financially secure and wants the assets to pass to her daughter, Chen, without incurring gift tax. Barrett''s attorney advises making a qualified disclaimer under IRC Section 2518 within nine months of her mother''s death. Analyze the transfer tax consequences if Barrett makes a timely qualified disclaimer versus simply giving the assets to Chen.', '["Both approaches produce identical transfer tax results because disclaimers are treated as gifts", "A qualified disclaimer causes the assets to pass to Chen as if Barrett predeceased her mother, avoiding gift tax, whereas a direct gift from Barrett would use her lifetime exemption or incur gift tax", "The disclaimer is less favorable because it triggers generation-skipping transfer tax when skipping Barrett", "A disclaimer can only redirect assets to the decedent''s spouse, not to other family members"]'::jsonb, 1, 'Under IRC Section 2518, a qualified disclaimer made within nine months causes the disclaimed property to pass as if the disclaimant predeceased the decedent, meaning Barrett is not treated as making a gift to Chen. By contrast, if Barrett accepts the inheritance and then gives $1,200,000 to Chen, it constitutes a taxable gift that uses her lifetime exemption. Choice C is incorrect because a disclaimer does not create a generation-skipping transfer — Chen takes directly from the grandmother''s estate under the estate plan or intestacy rules.', 'medium', 3)
;

COMMIT;
